def copy_single_photos(apps, schema_editor):
    """Starter posts had one optional photo; keep it as the post's first photo."""
    ItemPost = apps.get_model("core", "ItemPost")
    PostPhoto = apps.get_model("core", "PostPhoto")
    for post in ItemPost.objects.exclude(photo="").exclude(photo__isnull=True):
        PostPhoto.objects.create(post=post, image=post.photo.name, order=1)


def seed_categories(apps, schema_editor):
    Category = apps.get_model("core", "Category")
    for index, name in enumerate(STARTER_CATEGORIES, start=1):
        Category.objects.get_or_create(name=name, defaults={"sort_order": index * 10})


